t.script:
        var lang = 'ar';
        var dict = {
          ar: {
            title: 'تسجيل الحضور',
            code: 'كود الموظف',
            pin: 'الرقم السري',
            login: 'دخول',
            status: 'الحالة الحالية',
            ciSince: 'مسجّل الحضور منذ',
            gpsDetect: 'جار تحديد الموقع...',
            gpsErr: 'لا يمكن تحديد الموقع',
            gpsNotSupported: 'GPS غير متاح',
            checkin: '✅ تسجيل الحضور',
            checkout: '🏁 تسجيل الانصراف',
            processing: 'جار المعالجة...',
            in: '🟢 مسجّل الحضور',
            out: '🔴 غير مسجّل',
            mapsLink: 'فتح الموقع على Google Maps',
            logout: '← تسجيل الخروج',
            date: '📅 التاريخ',
            time: '🕒 الوقت',
            worked: '⏱ ساعات العمل',
            location: '📍 الموقع',
            fillBoth: 'يرجى إدخال الكود والرقم السري'
          },
          en: {
            title: 'Attendance',
            code: 'Employee Code',
            pin: 'PIN',
            login: 'Login',
            status: 'Current Status',
            ciSince: 'Checked in since',
            gpsDetect: 'Detecting location...',
            gpsErr: 'Could not detect location',
            gpsNotSupported: 'GPS not supported',
            checkin: '✅ Check In',
            checkout: '🏁 Check Out',
            processing: 'Processing...',
            in: '🟢 Checked In',
            out: '🔴 Not Checked In',
            mapsLink: 'Open location in Google Maps',
            logout: '← Logout',
            date: '📅 Date',
            time: '🕒 Time',
            worked: '⏱ Worked Hours',
            location: '📍 Location',
            fillBoth: 'Please enter both code and PIN'
          }
        };

        function t(key) { return dict[lang][key]; }

        function applyLang() {
          document.getElementById('txtTitle').innerHTML   = t('title');
          document.getElementById('lblCode').innerHTML    = t('code');
          document.getElementById('lblPin').innerHTML     = t('pin');
          document.getElementById('btnLoginText').innerHTML = t('login');
          document.getElementById('lblStatus').innerHTML  = t('status');
          document.getElementById('lblCiSince').innerHTML = t('ciSince');
          document.getElementById('gpsTxt').innerHTML     = t('gpsDetect');
          document.getElementById('btnInText').innerHTML  = t('checkin');
          document.getElementById('btnOutText').innerHTML = t('checkout');
          document.getElementById('mapsTxt').innerHTML    = t('mapsLink');
          document.getElementById('logoutTxt').innerHTML  = t('logout');
          document.body.style.direction = lang === 'ar' ? 'rtl' : 'ltr';
          document.getElementById('langToggle').textContent = lang === 'ar' ? 'EN' : 'AR';
        }

        document.getElementById('langToggle').addEventListener('click', function() {
          lang = lang === 'ar' ? 'en' : 'ar';
          applyLang();
        });

        applyLang();

        var gps = null;
        var currentCode = null;
        var currentPin  = null;

        var codeInput   = document.getElementById('codeInput');
        var pinInput    = document.getElementById('pinInput');
        var btnLogin    = document.getElementById('btnLogin');
        var loginErr    = document.getElementById('loginErr');
        var loginScreen = document.getElementById('loginScreen');
        var welcomeScreen = document.getElementById('welcomeScreen');
        var wName       = document.getElementById('wName');
        var wCode       = document.getElementById('wCode');
        var statusVal   = document.getElementById('statusVal');
        var ciRow       = document.getElementById('ciRow');
        var ciVal       = document.getElementById('ciVal');
        var gpsRow      = document.getElementById('gpsRow');
        var btnIn       = document.getElementById('btnIn');
        var btnOut      = document.getElementById('btnOut');
        var result      = document.getElementById('result');
        var rIcon       = document.getElementById('rIcon');
        var rMsg        = document.getElementById('rMsg');
        var rRows       = document.getElementById('rRows');
        var mapsBtn     = document.getElementById('mapsBtn');
        var logoutBtn   = document.getElementById('logoutBtn');

        // Clear fields on load to defeat autofill
        window.addEventListener('load', function() {
          setTimeout(function() {
            codeInput.value = '';
            pinInput.value  = '';
          }, 50);
          codeInput.focus();
        });

        btnLogin.addEventListener('click', doLogin);
        pinInput.addEventListener('keydown', function(e) {
          if (e.key === 'Enter') { doLogin(); }
        });

        function doLogin() {
          var code = codeInput.value.trim();
          var pin  = pinInput.value.trim();
          loginErr.style.display = 'none';

          if (!code || !pin) {
            loginErr.textContent = t('fillBoth');
            loginErr.style.display = 'block';
            return;
          }

          btnLogin.disabled = true;
          btnLogin.innerHTML = ' ' + t('processing');

          ajax('/drivers/attendance/login', {code: code, pin: pin}, function(res) {
            btnLogin.disabled  = false;
            btnLogin.innerHTML = '' + t('login') + '';

            if (res.error) {
              loginErr.textContent = res.error;
              loginErr.style.display = 'block';
              pinInput.value = '';
              pinInput.focus();
              return;
            }

            currentCode = code;
            currentPin  = pin;

            wName.textContent = res.employee_name;
            wCode.textContent = res.employee_code ? ('#' + res.employee_code) : '';

            loginScreen.style.display   = 'none';
            welcomeScreen.style.display = 'block';

            getGPS();
            loadStatus();
          });
        }

        function loadStatus() {
          ajax('/drivers/attendance/status', {code: currentCode, pin: currentPin, tz_name: getTz()}, function(res) {
            if (res.error) { statusVal.textContent = res.error; return; }
            if (res.is_checked_in) {
              statusVal.textContent = t('in');
              statusVal.className   = 'status-val in';
              if (res.check_in_full) {
                ciVal.textContent   = res.check_in_full;
                ciRow.style.display = 'block';
              }
              btnOut.style.display = 'block';
              btnIn.style.display  = 'none';
            } else {
              statusVal.textContent = t('out');
              statusVal.className   = 'status-val out';
              btnIn.style.display   = 'block';
              btnOut.style.display  = 'none';
            }
          });
        }

        function getGPS() {
          if (!navigator.geolocation) {
            setGps('err', t('gpsNotSupported'));
            return;
          }
          navigator.geolocation.getCurrentPosition(
            function(pos) {
              gps = {lat: pos.coords.latitude, lng: pos.coords.longitude};
              setGps('ok', '📍 ' + gps.lat.toFixed(5) + ', ' + gps.lng.toFixed(5));
            },
            function() { setGps('err', t('gpsErr')); },
            {enableHighAccuracy: true, timeout: 10000}
          );
        }

        function setGps(cls, txt) {
          gpsRow.className = 'gps-row ' + cls;
          gpsRow.innerHTML = txt;
        }

        btnIn.addEventListener('click',  function() { doAction('checkin');  });
        btnOut.addEventListener('click', function() { doAction('checkout'); });

        function doAction(action) {
          var btn = action === 'checkin' ? btnIn : btnOut;
          btn.disabled  = true;
          btn.innerHTML = ' ' + t('processing');
          result.style.display = 'none';

          var now = new Date();
          var pad = function(n) { return String(n).padStart(2,'0'); };
          var dt  = now.getFullYear()+'-'+pad(now.getMonth()+1)+'-'+pad(now.getDate())+' '+
                    pad(now.getHours())+':'+pad(now.getMinutes())+':'+pad(now.getSeconds());

          ajax('/drivers/attendance/'+action, {
            code           : currentCode,
            pin            : currentPin,
            latitude       : gps ? gps.lat : null,
            longitude      : gps ? gps.lng : null,
            location_label : gps ? gps.lat.toFixed(7)+','+gps.lng.toFixed(7) : '',
            local_datetime : dt,
            tz_name        : getTz(),
            tz_offset      : -now.getTimezoneOffset()
          }, function(res) {
            btn.disabled = false;
            btn.innerHTML = action === 'checkin'
              ? '' + t('checkin') + ''
              : '' + t('checkout') + '';

            if (res.error) {
              showResult('err', res.error, '', '❌');
              return;
            }

            var rows = '';
            rows += mkRow(t('date'), res.local_date || '');
            rows += mkRow(t('time'), res.local_time || '');
            if (res.worked_hours) {
              rows += mkRow(t('worked'), '' + res.worked_hours + '');
            }
            if (gps) {
              rows += mkRow(t('location'), gps.lat.toFixed(5) + ', ' + gps.lng.toFixed(5));
            }

            var icon = action === 'checkin' ? '🟢' : '🏁';
            showResult('ok', res.message, rows, icon);

            btnIn.style.display  = 'none';
            btnOut.style.display = 'none';
            ciRow.style.display  = 'none';

            if (gps) {
              mapsBtn.href          = 'https://www.google.com/maps?q='+gps.lat+','+gps.lng;
              mapsBtn.style.display = 'block';
            }
          });
        }

        function mkRow(label, value) {
          return '
'+label+''+value+'';
        }

        function showResult(type, msg, rows, icon) {
          result.className     = 'result ' + type;
          rIcon.innerHTML      = icon || '';
          rMsg.textContent     = msg;
          rRows.innerHTML      = rows || '';
          result.style.display = 'block';
        }

        logoutBtn.addEventListener('click', function() {
          currentCode = null;
          currentPin  = null;
          gps         = null;
          codeInput.value = '';
          pinInput.value  = '';
          loginErr.style.display      = 'none';
          welcomeScreen.style.display = 'none';
          loginScreen.style.display   = 'block';
          result.style.display        = 'none';
          mapsBtn.style.display       = 'none';
          ciRow.style.display         = 'none';
          codeInput.focus();
        });

        function getTz() {
          try { return Intl.DateTimeFormat().resolvedOptions().timeZone; } catch(e) { return 'UTC'; }
        }

        function ajax(url, params, cb) {
          var xhr = new XMLHttpRequest();
          xhr.open('POST', url, true);
          xhr.setRequestHeader('Content-Type','application/json');
          xhr.onload  = function() {
            try { cb(JSON.parse(xhr.responseText).result || {}); }
            catch(e) { cb({error:'Server error'}); }
          };
          xhr.onerror = function() { cb({error:'Network error'}); };
          xhr.send(JSON.stringify({jsonrpc:'2.0',method:'call',params:params}));
        }
